            submitted = 1;
            gSaveCmdArg1 = param1;
            gSaveCmdArg2 = param2;
            gSaveCmdArg3 = param3;
            gSaveCmdArg4 = param4;
            gSaveCmdArg5 = param5;
            gSaveCmdArg6 = param6;
            gSaveCmdArg7 = param7;
